using System;using System.IO;using ScoreModern.RecoveredFragments;
class InputSetupProof {
 static int W(byte[] b,int at){return BitConverter.ToInt16(b,at);}
 static InputSetupState Read(byte[] b){return new InputSetupState{Staff=W(b,0x83e0),LeftEnd=W(b,0x83e2),Vertical=W(b,0x83e4),Size=BitConverter.ToSingle(b,0x83e6),RightEnd=W(b,0x83ea),Spacing=W(b,0x84e8),LeftPosition=W(b,0x8530),RightPosition=W(b,0x8532),MeterTop=W(b,0x852c),MeterBottom=W(b,0x852e),Selected=W(b,0x852a)};}
 static int Main(string[] a){try{var s=Read(File.ReadAllBytes(a[0]));if(a[2]=="number")s.Numeric(float.Parse(a[3],System.Globalization.CultureInfo.InvariantCulture));else if(a[2]=="field")s.MoveField(int.Parse(a[3]));else s.SpacingLetter(a[3][0]);var e=Read(File.ReadAllBytes(a[1]));int[] actual={s.Staff,s.LeftEnd,s.Vertical,s.RightEnd,s.Spacing,s.LeftPosition,s.RightPosition,s.MeterTop,s.MeterBottom,s.Selected,BitConverter.ToInt32(BitConverter.GetBytes(s.Size),0)},expected={e.Staff,e.LeftEnd,e.Vertical,e.RightEnd,e.Spacing,e.LeftPosition,e.RightPosition,e.MeterTop,e.MeterBottom,e.Selected,BitConverter.ToInt32(BitConverter.GetBytes(e.Size),0)};for(int i=0;i<actual.Length;i++)if(actual[i]!=expected[i])throw new Exception("Setup field "+i+": "+actual[i]+" != "+expected[i]);Console.WriteLine("PASS eleven original setup state fields");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
